<?php
namespace Tests\Feature;use App\Models\{Room,RoomMember,User};use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class RoomRewardTest extends TestCase{use RefreshDatabase;public function test_member_claims_once_until_server_cooldown():void{$user=User::factory()->create();$room=Room::create(['name'=>'Rewards','host_user_id'=>$user->id]);RoomMember::create(['room_id'=>$room->id,'user_id'=>$user->id]);$this->actingAs($user)->getJson("/api/rooms/{$room->public_id}/reward")->assertOk()->assertJsonPath('available',true)->assertJsonPath('reward',5);$this->actingAs($user)->postJson("/api/rooms/{$room->public_id}/reward")->assertOk()->assertJsonPath('balance',5)->assertJsonPath('available',false);$this->actingAs($user)->postJson("/api/rooms/{$room->public_id}/reward")->assertUnprocessable();$this->assertSame(5,$user->wallet->refresh()->balance);$this->assertDatabaseCount('coin_transactions',1);}public function test_non_member_cannot_inspect_or_claim():void{$user=User::factory()->create();$host=User::factory()->create();$room=Room::create(['name'=>'Private','host_user_id'=>$host->id]);$this->actingAs($user)->getJson("/api/rooms/{$room->public_id}/reward")->assertForbidden();}}
